/**
 * The contract `label.tsx` and `label.web.tsx` both implement. Separate module
 * for the usual reason — Metro resolves `./label` to `label.web.tsx` on web, so
 * the web file cannot import shared types from `./label` without importing
 * itself.
 */
import type { ReactNode } from "react";

export type LabelProps = {
  /**
   * Associates the label with a control's `id`, so clicking it focuses the
   * control. Web only — there is no native equivalent, and the native file
   * ignores it rather than pretending otherwise.
   */
  htmlFor?: string | undefined;
  className?: string | undefined;
  children?: ReactNode;
};

/**
 * Shared between both implementations so the two cannot drift on type size or
 * weight. `peer-disabled:` is a DOM-only variant and simply does not apply on
 * native, where a disabled control does not dim its label.
 */
export const LABEL_CLASS =
  "text-foreground text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70";

/**
 * The native label: just text. `htmlFor` is accepted and ignored — there is no
 * label/control association on native, and a `TextInput` is focused by tapping
 * it rather than its caption.
 */

import { Text } from "react-native";
import { LABEL_CLASS, type LabelProps } from "@/components/ui/label-base";
import { cn } from "@/lib/utils";

function Label({ className, children }: LabelProps) {
  return <Text className={cn(LABEL_CLASS, className)}>{children}</Text>;
}

export { Label };

/**
 * The web label: radix, which is here for one thing — clicking the label
 * focuses the control named by `htmlFor`. That association has no native
 * counterpart, which is the whole reason for the split.
 *
 * It takes radix's `Label.Root` props whole — `id`, `onClick`, the `aria-*`
 * and `data-*` props — because it installs over a DOM app's shadcn label, and
 * shadcn's `FieldLabel` is typed as this label's props.
 */

import { Label as LabelPrimitive } from "radix-ui";
import type { ComponentPropsWithRef } from "react";
import { LABEL_CLASS } from "@/components/ui/label-base";
import { cn } from "@/lib/utils";

type LabelProps = Omit<ComponentPropsWithRef<typeof LabelPrimitive.Root>, "className"> & {
  className?: string | undefined;
};

function Label({ className, ...props }: LabelProps) {
  return (
    <LabelPrimitive.Root data-slot="label" {...props} className={cn(LABEL_CLASS, className)} />
  );
}

export { Label };
